#include <stdlib.h>
#include "config.h"

// Type definitions
typedef unsigned int uint;
typedef struct Node Node;

// Enum definition
enum Color {
    RED,
    GREEN,
    BLUE
};

// Struct definition
struct Node {
    int value;
    struct Node* next;
};

// Union definition
union Data {
    int integer;
    float floating;
    char character;
};

// Variable declarations
static int counter = 0;
const char* message = "Hello from C";
extern int global_var;

// Function declarations
int calculate(int x, int y);
void process_node(struct Node* node);

// Function definition with if statement
int calculate(int x, int y) {
    if (x > y) {
        return x - y;
    } else if (x == y) {
        return 0;
    } else {
        return y - x;
    }
}

// Function with for loop
void print_array(int* arr, int size) {
    for (int i = 0; i < size; i++) {
        printf("%d ", arr[i]);
    }
    printf("\n");
}

// Function with while loop
int sum_until(int limit) {
    int sum = 0;
    int i = 1;
    while (i <= limit) {
        sum += i;
        i++;
    }
    return sum;
}

// Function with do-while loop
int get_user_input() {
    int value;
    do {
        printf("Enter positive number: ");
        scanf("%d", &value);
    } while (value < 0);
    return value;
}

// Function with switch statement
const char* color_name(enum Color c) {
    switch (c) {
        case RED:
            return "red";
        case GREEN:
            return "green";
        case BLUE:
            return "blue";
        default:
            return "unknown";
    }
}

// Function definition for processing
void process_node(struct Node* node) {
    if (node != NULL) {
        printf("Node value: %d\n", node->value);
        process_node(node->next);
    }
}

// Main function with call expressions
int main(int argc, char* argv[]) {
    // Variable declarations
    int array[] = {1, 2, 3, 4, 5};
    int result;

    // Call expressions
    result = calculate(10, 5);
    print_array(array, 5);

    int sum = sum_until(10);
    printf("Sum: %d\n", sum);

    enum Color favorite = RED;
    printf("Color: %s\n", color_name(favorite));

    return EXIT_SUCCESS;
}
