    if (x > y) {
        return x - y;
    } else if (x == y) {
        return 0;
    } else {
        return y - x;
    }
}

// Function with for loop
void print_array(int* arr, int size) {
    for (int i = 0; i < size; i++) {
        printf("%d ", arr[i]);
    }
    printf("\n");
}

// Function with while loop
