    int sum = 0;
    int i = 1;
    while (i <= limit) {
        sum += i;
        i++;
    }
    return sum;
}

// Function with do-while loop
int get_user_input() {
    int value;
    do {
        printf("Enter positive number: ");
        scanf("%d", &value);
    } while (value < 0);
    return value;
}

// Function with switch statement
