    switch (c) {
        case RED:
            return "red";
        case GREEN:
            return "green";
        case BLUE:
            return "blue";
        default:
            return "unknown";
    }
}

// Function definition for processing
void process_node(struct Node* node) {
    if (node != NULL) {
        printf("Node value: %d\n", node->value);
        process_node(node->next);
    }
}

// Main function with call expressions
