 * Returns: factorial value or -1 on error
 */
int factorial(int n) {
    if (n < 0) {
        fprintf(stderr, "Error: negative input\n");
        return -1;
    }
    if (n == 0 || n == 1) {
        return 1;
    }
    return n * factorial(n - 1);
