 * String manipulation utility
 * Converts string to uppercase in-place
 */
void str_to_upper(char* str) {
    if (str == NULL) return;

    for (int i = 0; str[i] != '\0'; i++) {
        if (str[i] >= 'a' && str[i] <= 'z') {
            str[i] = str[i] - 'a' + 'A';
        }
    }
